    "meta.title": "Text-auf-den-Kopf-Stellen-Generator — Drehen, Spiegeln & Kapitälchen",
    "meta.description": "Text eingeben und per Unicode-Ähnlichkeitszeichen auf den Kopf gestellte, gespiegelte und Kapitälchen-Version erhalten. Kostenlos, Kopieren per Klick, alles im Browser berechnet.",
    "hero.lede": "Text eingeben oder einfügen und sofort auf den Kopf stellen, spiegeln oder in Kapitälchen umwandeln — kostenlos, Kopieren per Klick, direkt im Browser berechnet.",
    "tool.textLabel": "Dein Text",
    "tool.textPlaceholder": "Text hier eingeben oder einfügen…",
    "tool.clear": "Löschen",
